@page "/recipes/{Category}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>

@if (_recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetRecipesByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeShare</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <PageTitle>@_recipe.Title - RecipeShare</PageTitle>

    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-5">
            <h3>Ingredients</h3>
            <ul class="list-group">
                @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-7">
            <h3>Steps</h3>
            @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    </div>

    <div class="mt-4 p-3 border rounded">
        <h4>Rate this Recipe</h4>
        <StarRating RecipeId="_recipe.Id" CurrentRating="_recipe.AverageRating" RatingCount="_recipe.RatingCount" />
    </div>

    <a href="/recipes/@_recipe.Category" class="btn btn-outline-secondary mt-3">← Back to @_recipe.Category Recipes</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-2">
    <div class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
                  @onmouseover="() => _hoveredStar = star"
                  @onmouseout="() => _hoveredStar = 0"
                  @onclick="() => SubmitRating(star)"
                  role="button"
                  title="Rate @star stars">
                ★
            </span>
        }
    </div>
    <span class="text-muted ms-2">
        @if (_submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        else
        {
            <span>@CurrentRating.ToString("F1") avg (@RatingCount ratings)</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoveredStar;
    private int _selectedStar;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        _selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }

        _submitted = true;
    }
}

.star-rating {
    font-size: 1.8rem;
    cursor: pointer;
    user-select: none;
}

.star {
    color: #ccc;
    transition: color 0.15s;
}

.star.hovered,
.star.selected {
    color: #ffc107;
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@using System.ComponentModel.DataAnnotations
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_successMessage is not null)
{
    <div class="alert alert-success">@_successMessage</div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mt-3">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => _model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
            <option value="">-- Select a category --</option>
            @foreach (var cat in _categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => _model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="6" placeholder="1 cup flour&#10;2 eggs&#10;..." />
        <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="6" placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;..." />
        <ValidationMessage For="() => _model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel _model = new();
    private IReadOnlyList<string> _categories = [];
    private string? _successMessage;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };

        RecipeService.AddRecipe(recipe);
        _successMessage = $"\"{recipe.Title}\" has been submitted successfully!";
        _model = new();
    }

    private sealed class RecipeFormModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

